<template>
  <section class="community-page message-inbox"><div class="community-heading"><h1>消息中心</h1><span>{{ unread }} 条未读</span><button class="rd-icon-button" :disabled="busy||loading" title="刷新消息" aria-label="刷新消息" @click="load()"><RefreshCw :size="18" /></button><button class="rd-button" :disabled="busy || !unread" @click="mark()"><CheckCheck :size="18" />全部已读</button></div>
    <div class="message-filters"><nav class="rd-segments" aria-label="消息分类"><button v-for="option in categories" :key="option.id" :aria-pressed="category===option.id" :disabled="busy" @click="filter('category',option.id)">{{option.label}}</button></nav><label>状态<select v-model="state" :disabled="busy" @change="filter('state',state)"><option value="all">全部消息</option><option value="unread">未读消息</option><option value="archived">已归档</option></select></label></div>
    <p v-if="error" role="alert">{{ error }} <a v-if="unauthorized" href="/login/">登录</a><button v-else class="rd-button" @click="load">重试</button></p><p v-if="loading" role="status">加载消息...</p><p v-else-if="!items.length && !error">暂时没有消息</p>
    <article v-for="item in items" :key="item.id" class="notification-row" :class="{unread:!item.read_at&&!item.archived_at}"><div><span class="message-category">{{categories.find(c=>c.id===item.category)?.label||'审核结果'}}</span><a :href="safeHref(item.href)" @click="open($event,item)"><strong>{{ item.title }}</strong></a><p>{{ item.body }}</p><small>{{ new Date(item.created_at).toLocaleString('zh-CN') }}</small></div><div class="message-actions"><button v-if="!item.read_at&&!item.archived_at" class="task-icon-button" :disabled="busy" title="标记已读" aria-label="标记已读" @click="mark(item.id)"><Check :size="20" /></button><button class="task-icon-button" :disabled="busy" :title="item.archived_at?'恢复消息':'归档消息'" :aria-label="item.archived_at?'恢复消息':'归档消息'" @click="archive(item)"><component :is="item.archived_at?ArchiveRestore:Archive" :size="18" /></button></div></article>
    <nav class="rd-pagination" v-if="offset || more"><button class="rd-button" :disabled="busy || !offset" @click="page(-30)">上一页</button><span>{{offset/30+1}}</span><button class="rd-button" :disabled="busy || !more" @click="page(30)">下一页</button></nav>
  </section>
</template>
<script setup>
import { ref,onMounted,onUnmounted } from 'vue'
import { Archive,ArchiveRestore,Check,CheckCheck,RefreshCw } from 'lucide-vue-next'
import { communityRequest } from '../lib/community-api.mjs'
const items=ref([]),unread=ref(0),offset=ref(0),more=ref(false),busy=ref(false),loading=ref(true),error=ref(''),unauthorized=ref(false)
const category=ref(''),state=ref('all'),syncAt=ref(0),syncCursor=ref(null)
const categories=[{id:'',label:'全部'},{id:'result',label:'审核结果'},{id:'interaction',label:'评论回复'},{id:'level',label:'等级升级'},{id:'announcement',label:'站内通知'},{id:'review',label:'审核待办'}]
let disposed=false,revision=0,subscription,timer
async function load(quiet=false){const request=++revision;if(!quiet)loading.value=true;error.value='';try{const data=await communityRequest('/messages?'+new URLSearchParams({offset:offset.value,category:category.value,state:state.value}));if(disposed||request!==revision)return;items.value=data.items;unread.value=data.unread;more.value=data.has_more;syncAt.value=data.sync_at||Date.now();syncCursor.value=data.sync_cursor??null;unauthorized.value=false;if(!items.value.length&&offset.value){offset.value=Math.max(0,offset.value-30);return load(quiet)}}catch(e){if(!disposed&&request===revision){error.value=e.message;unauthorized.value=e.status===401;items.value=[]}}finally{if(request===revision)loading.value=false}}
async function mark(id){if(busy.value)return;busy.value=true;const run=revision;try{await communityRequest('/messages/read',{method:'POST',body:id?{id}:{before:syncAt.value,...(syncCursor.value!==null?{cursor:syncCursor.value}:{})}});if(disposed||run!==revision)return;await load();window.dispatchEvent(new CustomEvent('rd:community-updated'))}catch(e){if(!disposed&&run===revision)error.value=e.message}finally{busy.value=false}}
function safeHref(href){return typeof href==='string'&&href.startsWith('/')&&!href.startsWith('//')&&!/[\\\u0000-\u001f]/.test(href)?href:'/messages/'}
async function open(event,item){if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();if(busy.value)return;const run=revision;try{if(!item.read_at&&!item.archived_at)await communityRequest('/messages/read',{method:'POST',body:{id:item.id}});if(!disposed&&run===revision){window.dispatchEvent(new CustomEvent('rd:community-updated'));window.location.assign(safeHref(item.href))}}catch(e){if(!disposed)error.value=e.message}}
async function archive(item){if(busy.value)return;busy.value=true;const run=revision;try{await communityRequest('/messages/'+encodeURIComponent(item.id)+(item.archived_at?'/restore':'/archive'),{method:'POST',body:{}});if(disposed||run!==revision)return;await load();window.dispatchEvent(new CustomEvent('rd:community-updated'))}catch(e){if(!disposed&&run===revision)error.value=e.message}finally{busy.value=false}}
function filter(key,value){if(key==='category')category.value=value;else state.value=value;offset.value=0;load()}
function page(delta){offset.value+=delta;load()}
function refreshVisible(){if(!document.hidden&&!busy.value&&!loading.value&&!unauthorized.value)load(true)}
onMounted(()=>{load();timer=setInterval(refreshVisible,30000);document.addEventListener('visibilitychange',refreshVisible);subscription=window.__api?.auth.onAuthStateChange(event=>{if(event!=='INITIAL_SESSION'){items.value=[];unread.value=0;offset.value=0;load()}}).data.subscription})
onUnmounted(()=>{disposed=true;++revision;clearInterval(timer);document.removeEventListener('visibilitychange',refreshVisible);subscription?.unsubscribe()})
</script>
<style scoped>
:global(body:has(.message-inbox) .studio-backdrop){opacity:.15}
.message-inbox .community-heading h1{min-width:max-content}
@media(max-width:600px){.message-inbox .community-heading h1{flex-basis:100%}.message-inbox .community-heading>span{margin-right:auto}}
.message-inbox{max-width:1000px}.message-filters{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:24px 0}.message-filters nav{max-width:100%;overflow-x:auto}.message-filters nav button{white-space:nowrap}.message-filters label{display:flex;align-items:center;gap:8px;font-size:14px;color:var(--vp-c-text-2)}.message-filters select{background:var(--vp-c-bg);color:var(--vp-c-text-1);padding:9px 12px;border:1px solid var(--vp-c-divider);border-radius:6px}.notification-row{gap:20px}.notification-row>div:first-child{min-width:0;flex:1}.notification-row p{white-space:pre-wrap;overflow-wrap:anywhere}.notification-row a{overflow-wrap:anywhere}.message-actions{display:flex;gap:8px;flex:none}.message-category{display:block;font-size:12px;color:var(--vp-c-brand-1);margin-bottom:6px}@media(max-width:600px){.message-actions{flex-direction:column}.message-inbox .community-heading{flex-wrap:wrap}.message-filters{align-items:stretch}.message-filters nav{width:100%}}
</style>
